INSERT INTO sources (id, master_row, company, posting_url, talent_url, channel, adapter, verification, confidence, resume_upload, job_alerts, enabled, checked_at) VALUES ('p5-0810-atrium-health', 2421, 'Atrium Health (Advocate)', 'https://aah.wd5.myworkdayjobs.com/en-US/External', 'https://careers.advocatehealth.com/', '공식 채용공고 검색·지원', 'workday', 'not_audited', 'medium', 'unknown', 'unknown', 1, '2026-08-25') ON CONFLICT(id) DO UPDATE SET master_row = excluded.master_row, company = excluded.company, posting_url = excluded.posting_url, talent_url = excluded.talent_url, channel = excluded.channel, adapter = excluded.adapter, verification = excluded.verification, confidence = excluded.confidence, resume_upload = excluded.resume_upload, job_alerts = excluded.job_alerts, enabled = excluded.enabled, checked_at = excluded.checked_at;
